import { readdirSync } from 'fs';
import { join } from 'path';
import { loadFhirBundle } from '../loaders/fhir-loader';
import { getResourcesByType } from '../schema';

/**
 * Patient Data Validation - Check for outliers in patient demographics
 */

const DATA_PATH = '/Users/hrishioa/Dropbox/Projects/Southbridge/experiments/sealed-agents/tests/healthcare-ehr-langton/data/fhir';

interface PatientOutliers {
  birthDates: {
    veryOld: any[];
    future: any[];
    january1st: any[];
    ageDistribution: { [decade: string]: number };
  };
  names: {
    nonStandardPattern: any[];
    missingNumbers: any[];
    extremelyLong: any[];
    specialCharacters: any[];
  };
  identifiers: {
    invalidSSN: any[];
    missingTypes: any[];
    duplicateValues: { [key: string]: any[] };
  };
  demographics: {
    genderDistribution: { [gender: string]: number };
    maritalStatusDistribution: { [status: string]: number };
    languageDistribution: { [language: string]: number };
  };
  addresses: {
    missingComponents: any[];
    invalidPostalCodes: any[];
    stateDistribution: { [state: string]: number };
  };
  contacts: {
    invalidPhoneNumbers: any[];
    missingContacts: any[];
    phonePatterns: { [pattern: string]: number };
  };
}

export function validatePatientData(sampleSize: number = 100): PatientOutliers {
  const files = readdirSync(DATA_PATH).filter(f => f.endsWith('.json')).slice(0, sampleSize);

  const outliers: PatientOutliers = {
    birthDates: {
      veryOld: [],
      future: [],
      january1st: [],
      ageDistribution: {},
    },
    names: {
      nonStandardPattern: [],
      missingNumbers: [],
      extremelyLong: [],
      specialCharacters: [],
    },
    identifiers: {
      invalidSSN: [],
      missingTypes: [],
      duplicateValues: {},
    },
    demographics: {
      genderDistribution: {},
      maritalStatusDistribution: {},
      languageDistribution: {},
    },
    addresses: {
      missingComponents: [],
      invalidPostalCodes: [],
      stateDistribution: {},
    },
    contacts: {
      invalidPhoneNumbers: [],
      missingContacts: [],
      phonePatterns: {},
    },
  };

  console.log(`🔍 Validating patient data in ${files.length} files...\n`);

  const currentYear = new Date().getFullYear();
  const ssnPattern = /^\d{3}-\d{2}-\d{4}$/;
  const phonePattern = /^\d{3}-\d{3}-\d{4}$/;
  const postalCodePattern = /^\d{5}(-\d{4})?$/;
  const syntheaNamePattern = /^[A-Za-z]+\d+$/;

  let totalPatients = 0;
  const allSSNs: string[] = [];

  for (const [index, fileName] of files.entries()) {
    if (index % 20 === 0) {
      console.log(`Progress: ${index}/${files.length} files`);
    }

    const result = loadFhirBundle(join(DATA_PATH, fileName));
    if (!result.success || !result.bundle) continue;

    const patients = getResourcesByType(result.bundle, 'Patient');

    patients.forEach(patient => {
      totalPatients++;

      // Birth date validation
      if (patient.birthDate) {
        const birthYear = parseInt(patient.birthDate.split('-')[0]);
        const age = currentYear - birthYear;

        if (age > 120) {
          outliers.birthDates.veryOld.push({
            file: fileName,
            id: patient.id,
            birthDate: patient.birthDate,
            age
          });
        }

        if (birthYear > currentYear) {
          outliers.birthDates.future.push({
            file: fileName,
            id: patient.id,
            birthDate: patient.birthDate,
          });
        }

        if (patient.birthDate.endsWith('-01-01')) {
          outliers.birthDates.january1st.push({
            file: fileName,
            id: patient.id,
            birthDate: patient.birthDate,
          });
        }

        // Age distribution
        const decade = Math.floor(age / 10) * 10;
        const decadeKey = `${decade}s`;
        outliers.birthDates.ageDistribution[decadeKey] = (outliers.birthDates.ageDistribution[decadeKey] || 0) + 1;
      }

      // Name validation
      if (patient.name && patient.name[0]) {
        const name = patient.name[0];

        // Check given names
        if (name.given) {
          name.given.forEach(given => {
            if (!syntheaNamePattern.test(given)) {
              outliers.names.nonStandardPattern.push({
                file: fileName,
                id: patient.id,
                name: given,
                type: 'given'
              });
            }

            if (given.length > 20) {
              outliers.names.extremelyLong.push({
                file: fileName,
                id: patient.id,
                name: given,
                length: given.length
              });
            }

            if (/[^a-zA-Z0-9]/.test(given)) {
              outliers.names.specialCharacters.push({
                file: fileName,
                id: patient.id,
                name: given,
                type: 'given'
              });
            }
          });
        }

        // Check family name
        if (name.family) {
          if (!syntheaNamePattern.test(name.family)) {
            outliers.names.nonStandardPattern.push({
              file: fileName,
              id: patient.id,
              name: name.family,
              type: 'family'
            });
          }

          if (name.family.length > 20) {
            outliers.names.extremelyLong.push({
              file: fileName,
              id: patient.id,
              name: name.family,
              length: name.family.length
            });
          }
        }
      }

      // Identifier validation
      if (patient.identifier) {
        const identifierTypes = new Set();

        patient.identifier.forEach(id => {
          if (id.type?.text) {
            identifierTypes.add(id.type.text);
          }

          // SSN validation
          if (id.type?.text === 'Social Security Number' && id.value) {
            allSSNs.push(id.value);
            if (!ssnPattern.test(id.value)) {
              outliers.identifiers.invalidSSN.push({
                file: fileName,
                patientId: patient.id,
                ssn: id.value
              });
            }
          }
        });

        // Check for missing standard identifier types
        const expectedTypes = ['Social Security Number', 'Medical Record Number', 'Driver\'s license number'];
        expectedTypes.forEach(type => {
          if (!identifierTypes.has(type)) {
            outliers.identifiers.missingTypes.push({
              file: fileName,
              patientId: patient.id,
              missingType: type
            });
          }
        });
      }

      // Demographics
      if (patient.gender) {
        outliers.demographics.genderDistribution[patient.gender] = 
          (outliers.demographics.genderDistribution[patient.gender] || 0) + 1;
      }

      if (patient.maritalStatus?.text) {
        outliers.demographics.maritalStatusDistribution[patient.maritalStatus.text] = 
          (outliers.demographics.maritalStatusDistribution[patient.maritalStatus.text] || 0) + 1;
      }

      if (patient.communication && patient.communication[0]?.language?.text) {
        const lang = patient.communication[0].language.text;
        outliers.demographics.languageDistribution[lang] = 
          (outliers.demographics.languageDistribution[lang] || 0) + 1;
      }

      // Address validation
      if (patient.address && patient.address[0]) {
        const address = patient.address[0];

        // Missing components
        if (!address.line || !address.city || !address.state || !address.postalCode) {
          outliers.addresses.missingComponents.push({
            file: fileName,
            patientId: patient.id,
            address: address
          });
        }

        // Invalid postal code
        if (address.postalCode && !postalCodePattern.test(address.postalCode)) {
          outliers.addresses.invalidPostalCodes.push({
            file: fileName,
            patientId: patient.id,
            postalCode: address.postalCode
          });
        }

        // State distribution
        if (address.state) {
          outliers.addresses.stateDistribution[address.state] = 
            (outliers.addresses.stateDistribution[address.state] || 0) + 1;
        }
      }

      // Contact validation
      if (patient.telecom && patient.telecom[0]) {
        const contact = patient.telecom[0];

        if (contact.system === 'phone' && contact.value) {
          if (!phonePattern.test(contact.value)) {
            outliers.contacts.invalidPhoneNumbers.push({
              file: fileName,
              patientId: patient.id,
              phone: contact.value
            });
          }

          // Phone pattern analysis
          const pattern = contact.value.replace(/\d/g, 'X');
          outliers.contacts.phonePatterns[pattern] = (outliers.contacts.phonePatterns[pattern] || 0) + 1;
        }
      } else {
        outliers.contacts.missingContacts.push({
          file: fileName,
          patientId: patient.id
        });
      }
    });
  }

  // Check for duplicate SSNs
  const ssnCounts: { [ssn: string]: number } = {};
  allSSNs.forEach(ssn => {
    ssnCounts[ssn] = (ssnCounts[ssn] || 0) + 1;
  });

  Object.entries(ssnCounts).forEach(([ssn, count]) => {
    if (count > 1) {
      outliers.identifiers.duplicateValues[ssn] = allSSNs.filter(s => s === ssn).map(s => ({ ssn, count }));
    }
  });

  // Print results
  console.log(`\n📊 Patient Data Validation Results (${totalPatients} patients):\n`);

  console.log('🎂 Birth Date Outliers:');
  console.log(`  - Very old patients (>120 years): ${outliers.birthDates.veryOld.length}`);
  console.log(`  - Future birth dates: ${outliers.birthDates.future.length}`);
  console.log(`  - January 1st birth dates: ${outliers.birthDates.january1st.length}`);
  console.log(`  - Age distribution:`, Object.entries(outliers.birthDates.ageDistribution)
    .sort(([a], [b]) => a.localeCompare(b))
    .map(([decade, count]) => `${decade}: ${count}`).join(', '));

  console.log('\n👤 Name Outliers:');
  console.log(`  - Non-standard pattern: ${outliers.names.nonStandardPattern.length}`);
  console.log(`  - Extremely long names: ${outliers.names.extremelyLong.length}`);
  console.log(`  - Special characters: ${outliers.names.specialCharacters.length}`);

  console.log('\n🆔 Identifier Outliers:');
  console.log(`  - Invalid SSN format: ${outliers.identifiers.invalidSSN.length}`);
  console.log(`  - Duplicate SSNs: ${Object.keys(outliers.identifiers.duplicateValues).length}`);
  console.log(`  - Missing identifier types: ${outliers.identifiers.missingTypes.length}`);

  console.log('\n📊 Demographics:');
  console.log(`  - Gender distribution:`, outliers.demographics.genderDistribution);
  console.log(`  - Marital status distribution:`, Object.entries(outliers.demographics.maritalStatusDistribution)
    .sort(([,a], [,b]) => b - a).slice(0, 5));

  console.log('\n🏠 Address Outliers:');
  console.log(`  - Missing components: ${outliers.addresses.missingComponents.length}`);
  console.log(`  - Invalid postal codes: ${outliers.addresses.invalidPostalCodes.length}`);
  console.log(`  - Top 5 states:`, Object.entries(outliers.addresses.stateDistribution)
    .sort(([,a], [,b]) => b - a).slice(0, 5).map(([state, count]) => `${state}: ${count}`).join(', '));

  console.log('\n📱 Contact Outliers:');
  console.log(`  - Invalid phone numbers: ${outliers.contacts.invalidPhoneNumbers.length}`);
  console.log(`  - Missing contacts: ${outliers.contacts.missingContacts.length}`);
  console.log(`  - Phone patterns:`, Object.entries(outliers.contacts.phonePatterns).slice(0, 3));

  return outliers;
}

if (require.main === module) {
  const sampleSize = process.argv[2] ? parseInt(process.argv[2]) : 100;
  validatePatientData(sampleSize);
}

import { readdirSync } from 'fs';
import { join } from 'path';
import { loadFhirBundle } from '../loaders/fhir-loader';
import { getResourcesByType } from '../schema';

/**
 * Observation Data Validation - Check for outliers in vital signs and lab values
 */

const DATA_PATH = '/Users/hrishioa/Dropbox/Projects/Southbridge/experiments/sealed-agents/tests/healthcare-ehr-langton/data/fhir';

// Clinical reference ranges for common observations
const CLINICAL_RANGES = {
  'Body Height': { min: 50, max: 250, unit: 'cm' }, // 1.6 feet to 8.2 feet
  'Body Weight': { min: 1, max: 500, unit: 'kg' }, // 2.2 lbs to 1100 lbs
  'Body mass index (BMI) [Ratio]': { min: 10, max: 80, unit: 'kg/m2' },
  'Heart rate': { min: 20, max: 250, unit: '/min' },
  'Respiratory rate': { min: 5, max: 60, unit: '/min' },
  'Pain severity - 0-10 verbal numeric rating [Score] - Reported': { min: 0, max: 10, unit: '{score}' },
  'Hemoglobin [Mass/volume] in Blood': { min: 5, max: 20, unit: 'g/dL' },
  'Leukocytes [#/volume] in Blood by Automated count': { min: 1000, max: 50000, unit: '/uL' },
  'Erythrocytes [#/volume] in Blood by Automated count': { min: 2000000, max: 8000000, unit: '/uL' },
  'Platelet count [#/volume] in Blood by Automated count': { min: 50000, max: 1000000, unit: '/uL' },
  'Glucose [Mass/volume] in Blood': { min: 30, max: 800, unit: 'mg/dL' },
  'Cholesterol [Mass/volume] in Serum or Plasma': { min: 80, max: 500, unit: 'mg/dL' },
  'Creatinine [Mass/volume] in Serum or Plasma': { min: 0.3, max: 15, unit: 'mg/dL' },
};

interface ObservationOutliers {
  valueOutliers: {
    tooLow: any[];
    tooHigh: any[];
    impossible: any[];
  };
  unitInconsistency: {
    [observationType: string]: { [unit: string]: number };
  };
  statusDistribution: { [status: string]: number };
  codeDistribution: { [code: string]: number };
  missingValues: any[];
  negativeValues: any[];
  temporalOutliers: {
    futureObservations: any[];
    veryOldObservations: any[];
  };
  duplicateObservations: any[];
}

export function validateObservationData(sampleSize: number = 50): ObservationOutliers {
  const files = readdirSync(DATA_PATH).filter(f => f.endsWith('.json')).slice(0, sampleSize);

  const outliers: ObservationOutliers = {
    valueOutliers: {
      tooLow: [],
      tooHigh: [],
      impossible: [],
    },
    unitInconsistency: {},
    statusDistribution: {},
    codeDistribution: {},
    missingValues: [],
    negativeValues: [],
    temporalOutliers: {
      futureObservations: [],
      veryOldObservations: [],
    },
    duplicateObservations: [],
  };

  console.log(`🔍 Validating observation data in ${files.length} files...\n`);

  let totalObservations = 0;
  const currentYear = new Date().getFullYear();
  const observationKeys = new Set<string>();

  for (const [index, fileName] of files.entries()) {
    if (index % 10 === 0) {
      console.log(`Progress: ${index}/${files.length} files`);
    }

    const result = loadFhirBundle(join(DATA_PATH, fileName));
    if (!result.success || !result.bundle) continue;

    const observations = getResourcesByType(result.bundle, 'Observation');

    observations.forEach(obs => {
      totalObservations++;

      // Status distribution
      if (obs.status) {
        outliers.statusDistribution[obs.status] = (outliers.statusDistribution[obs.status] || 0) + 1;
      }

      // Code distribution
      const codeText = obs.code?.text || obs.code?.coding?.[0]?.display;
      if (codeText) {
        outliers.codeDistribution[codeText] = (outliers.codeDistribution[codeText] || 0) + 1;
        observationKeys.add(codeText);
      }

      // Temporal validation
      if (obs.effectiveDateTime) {
        const obsYear = parseInt(obs.effectiveDateTime.split('-')[0]);

        if (obsYear > currentYear) {
          outliers.temporalOutliers.futureObservations.push({
            file: fileName,
            id: obs.id,
            date: obs.effectiveDateTime,
            type: codeText,
          });
        }

        if (obsYear < 1900) {
          outliers.temporalOutliers.veryOldObservations.push({
            file: fileName,
            id: obs.id,
            date: obs.effectiveDateTime,
            type: codeText,
          });
        }
      }

      // Value validation
      if (obs.valueQuantity) {
        const value = obs.valueQuantity.value;
        const unit = obs.valueQuantity.unit;

        if (value === undefined || value === null) {
          outliers.missingValues.push({
            file: fileName,
            id: obs.id,
            type: codeText,
          });
          return;
        }

        // Check for negative values where inappropriate
        if (value < 0 && codeText && !codeText.toLowerCase().includes('change')) {
          outliers.negativeValues.push({
            file: fileName,
            id: obs.id,
            type: codeText,
            value,
            unit,
          });
        }

        // Unit consistency check
        if (codeText && unit) {
          if (!outliers.unitInconsistency[codeText]) {
            outliers.unitInconsistency[codeText] = {};
          }
          outliers.unitInconsistency[codeText][unit] = (outliers.unitInconsistency[codeText][unit] || 0) + 1;
        }

        // Clinical range validation
        if (codeText && CLINICAL_RANGES[codeText]) {
          const range = CLINICAL_RANGES[codeText];

          if (value < range.min) {
            outliers.valueOutliers.tooLow.push({
              file: fileName,
              id: obs.id,
              type: codeText,
              value,
              unit,
              expectedMin: range.min,
              expectedUnit: range.unit,
            });
          }

          if (value > range.max) {
            outliers.valueOutliers.tooHigh.push({
              file: fileName,
              id: obs.id,
              type: codeText,
              value,
              unit,
              expectedMax: range.max,
              expectedUnit: range.unit,
            });
          }

          // Check for impossible values (extreme outliers)
          if (value < range.min * 0.1 || value > range.max * 2) {
            outliers.valueOutliers.impossible.push({
              file: fileName,
              id: obs.id,
              type: codeText,
              value,
              unit,
              range: `${range.min}-${range.max} ${range.unit}`,
            });
          }
        }
      }
    });
  }

  // Print results
  console.log(`\n📊 Observation Data Validation Results (${totalObservations} observations):\n`);

  console.log('📈 Value Outliers:');
  console.log(`  - Too low values: ${outliers.valueOutliers.tooLow.length}`);
  console.log(`  - Too high values: ${outliers.valueOutliers.tooHigh.length}`);
  console.log(`  - Impossible values: ${outliers.valueOutliers.impossible.length}`);
  console.log(`  - Missing values: ${outliers.missingValues.length}`);
  console.log(`  - Negative values: ${outliers.negativeValues.length}`);

  if (outliers.valueOutliers.tooLow.length > 0) {
    console.log('\n  📉 Sample Too Low Values:');
    outliers.valueOutliers.tooLow.slice(0, 3).forEach(item => {
      console.log(`    - ${item.type}: ${item.value} ${item.unit} (expected min: ${item.expectedMin} ${item.expectedUnit})`);
    });
  }

  if (outliers.valueOutliers.tooHigh.length > 0) {
    console.log('\n  📈 Sample Too High Values:');
    outliers.valueOutliers.tooHigh.slice(0, 3).forEach(item => {
      console.log(`    - ${item.type}: ${item.value} ${item.unit} (expected max: ${item.expectedMax} ${item.expectedUnit})`);
    });
  }

  if (outliers.valueOutliers.impossible.length > 0) {
    console.log('\n  🚨 Sample Impossible Values:');
    outliers.valueOutliers.impossible.slice(0, 3).forEach(item => {
      console.log(`    - ${item.type}: ${item.value} ${item.unit} (expected range: ${item.range})`);
    });
  }

  console.log('\n📊 Status Distribution:');
  Object.entries(outliers.statusDistribution)
    .sort(([,a], [,b]) => b - a)
    .forEach(([status, count]) => {
      console.log(`  - ${status}: ${count}`);
    });

  console.log('\n🔬 Top 10 Observation Types:');
  Object.entries(outliers.codeDistribution)
    .sort(([,a], [,b]) => b - a)
    .slice(0, 10)
    .forEach(([type, count]) => {
      console.log(`  - ${type}: ${count}`);
    });

  console.log('\n⚠️  Unit Inconsistencies:');
  Object.entries(outliers.unitInconsistency)
    .filter(([, units]) => Object.keys(units).length > 1)
    .slice(0, 5)
    .forEach(([type, units]) => {
      console.log(`  - ${type}: ${Object.entries(units).map(([unit, count]) => `${unit}(${count})`).join(', ')}`);
    });

  console.log('\n🕐 Temporal Outliers:');
  console.log(`  - Future observations: ${outliers.temporalOutliers.futureObservations.length}`);
  console.log(`  - Very old observations: ${outliers.temporalOutliers.veryOldObservations.length}`);

  if (outliers.negativeValues.length > 0) {
    console.log('\n➖ Sample Negative Values:');
    outliers.negativeValues.slice(0, 3).forEach(item => {
      console.log(`  - ${item.type}: ${item.value} ${item.unit}`);
    });
  }

  return outliers;
}

if (require.main === module) {
  const sampleSize = process.argv[2] ? parseInt(process.argv[2]) : 50;
  validateObservationData(sampleSize);
}

import { readdirSync } from 'fs';
import { join } from 'path';
import { loadFhirBundle } from '../loaders/fhir-loader';
import { getResourcesByType } from '../schema';

/**
 * Encounter Data Validation - Check for outliers in encounters
 */

const DATA_PATH = '/Users/hrishioa/Dropbox/Projects/Southbridge/experiments/sealed-agents/tests/healthcare-ehr-langton/data/fhir';

interface EncounterOutliers {
  durations: {
    veryShort: any[]; // < 1 minute
    veryLong: any[]; // > 24 hours
    negative: any[]; // end before start
    noEndTime: any[];
    statistics: {
      min: number;
      max: number;
      average: number;
      median: number;
    };
  };
  types: {
    distribution: { [type: string]: number };
    unusual: any[];
  };
  status: {
    distribution: { [status: string]: number };
    nonFinished: any[];
  };
  classes: {
    distribution: { [class: string]: number };
    unusual: any[];
  };
  temporal: {
    sameTime: any[]; // Multiple encounters at exact same time
    overlap: any[]; // Overlapping encounters for same patient
    clustering: { [hour: string]: number }; // Hour of day distribution
  };
  participants: {
    noParticipants: any[];
    manyParticipants: any[];
    participantStats: {
      min: number;
      max: number;
      average: number;
    };
  };
}

function parseDateTime(dateTime: string): Date {
  return new Date(dateTime);
}

function calculateDuration(start: string, end: string): number {
  const startTime = parseDateTime(start);
  const endTime = parseDateTime(end);
  return endTime.getTime() - startTime.getTime();
}

export function validateEncounterData(sampleSize: number = 50): EncounterOutliers {
  const files = readdirSync(DATA_PATH).filter(f => f.endsWith('.json')).slice(0, sampleSize);

  const outliers: EncounterOutliers = {
    durations: {
      veryShort: [],
      veryLong: [],
      negative: [],
      noEndTime: [],
      statistics: { min: Infinity, max: -Infinity, average: 0, median: 0 },
    },
    types: {
      distribution: {},
      unusual: [],
    },
    status: {
      distribution: {},
      nonFinished: [],
    },
    classes: {
      distribution: {},
      unusual: [],
    },
    temporal: {
      sameTime: [],
      overlap: [],
      clustering: {},
    },
    participants: {
      noParticipants: [],
      manyParticipants: [],
      participantStats: { min: Infinity, max: -Infinity, average: 0 },
    },
  };

  console.log(`🔍 Validating encounter data in ${files.length} files...\n`);

  let totalEncounters = 0;
  const durations: number[] = [];
  const participantCounts: number[] = [];
  const patientEncounters: { [patientId: string]: any[] } = {};

  for (const [index, fileName] of files.entries()) {
    if (index % 10 === 0) {
      console.log(`Progress: ${index}/${files.length} files`);
    }

    const result = loadFhirBundle(join(DATA_PATH, fileName));
    if (!result.success || !result.bundle) continue;

    const encounters = getResourcesByType(result.bundle, 'Encounter');
    const patients = getResourcesByType(result.bundle, 'Patient');
    const patientId = patients[0]?.id;

    if (patientId) {
      patientEncounters[patientId] = encounters;
    }

    encounters.forEach(encounter => {
      totalEncounters++;

      // Status distribution
      if (encounter.status) {
        outliers.status.distribution[encounter.status] = 
          (outliers.status.distribution[encounter.status] || 0) + 1;

        if (encounter.status !== 'finished') {
          outliers.status.nonFinished.push({
            file: fileName,
            id: encounter.id,
            status: encounter.status,
          });
        }
      }

      // Type distribution
      const encounterType = encounter.type?.[0]?.text || encounter.type?.[0]?.coding?.[0]?.display;
      if (encounterType) {
        outliers.types.distribution[encounterType] = 
          (outliers.types.distribution[encounterType] || 0) + 1;
      }

      // Class distribution
      const encounterClass = encounter.class?.display || encounter.class?.code;
      if (encounterClass) {
        outliers.classes.distribution[encounterClass] = 
          (outliers.classes.distribution[encounterClass] || 0) + 1;
      }

      // Duration analysis
      if (encounter.period) {
        const startTime = encounter.period.start;
        const endTime = encounter.period.end;

        if (startTime && endTime) {
          const duration = calculateDuration(startTime, endTime);
          durations.push(duration);

          // Update statistics
          outliers.durations.statistics.min = Math.min(outliers.durations.statistics.min, duration);
          outliers.durations.statistics.max = Math.max(outliers.durations.statistics.max, duration);

          // Check for outliers
          if (duration < 60000) { // < 1 minute
            outliers.durations.veryShort.push({
              file: fileName,
              id: encounter.id,
              duration: duration / 1000, // seconds
              type: encounterType,
              start: startTime,
              end: endTime,
            });
          }

          if (duration > 24 * 60 * 60 * 1000) { // > 24 hours
            outliers.durations.veryLong.push({
              file: fileName,
              id: encounter.id,
              duration: duration / (60 * 60 * 1000), // hours
              type: encounterType,
              start: startTime,
              end: endTime,
            });
          }

          if (duration < 0) { // Negative duration
            outliers.durations.negative.push({
              file: fileName,
              id: encounter.id,
              duration: duration / 1000, // seconds
              type: encounterType,
              start: startTime,
              end: endTime,
            });
          }
        } else if (startTime && !endTime) {
          outliers.durations.noEndTime.push({
            file: fileName,
            id: encounter.id,
            type: encounterType,
            start: startTime,
          });
        }
      }

      // Participant analysis
      const participantCount = encounter.participant?.length || 0;
      participantCounts.push(participantCount);

      outliers.participants.participantStats.min = Math.min(outliers.participants.participantStats.min, participantCount);
      outliers.participants.participantStats.max = Math.max(outliers.participants.participantStats.max, participantCount);

      if (participantCount === 0) {
        outliers.participants.noParticipants.push({
          file: fileName,
          id: encounter.id,
          type: encounterType,
        });
      }

      if (participantCount > 5) {
        outliers.participants.manyParticipants.push({
          file: fileName,
          id: encounter.id,
          type: encounterType,
          participantCount,
        });
      }

      // Temporal clustering (hour of day)
      if (encounter.period?.start) {
        const hour = new Date(encounter.period.start).getHours();
        outliers.temporal.clustering[hour] = (outliers.temporal.clustering[hour] || 0) + 1;
      }
    });
  }

  // Calculate statistics
  if (durations.length > 0) {
    outliers.durations.statistics.average = durations.reduce((a, b) => a + b, 0) / durations.length;
    const sortedDurations = durations.sort((a, b) => a - b);
    outliers.durations.statistics.median = sortedDurations[Math.floor(sortedDurations.length / 2)];
  }

  if (participantCounts.length > 0) {
    outliers.participants.participantStats.average = participantCounts.reduce((a, b) => a + b, 0) / participantCounts.length;
  }

  // Check for overlapping encounters per patient
  Object.entries(patientEncounters).forEach(([patientId, encounters]) => {
    for (let i = 0; i < encounters.length; i++) {
      for (let j = i + 1; j < encounters.length; j++) {
        const enc1 = encounters[i];
        const enc2 = encounters[j];

        if (enc1.period?.start && enc1.period?.end && enc2.period?.start && enc2.period?.end) {
          const start1 = parseDateTime(enc1.period.start);
          const end1 = parseDateTime(enc1.period.end);
          const start2 = parseDateTime(enc2.period.start);
          const end2 = parseDateTime(enc2.period.end);

          // Check for overlap
          if (start1 < end2 && start2 < end1) {
            outliers.temporal.overlap.push({
              patientId,
              encounter1: { id: enc1.id, start: enc1.period.start, end: enc1.period.end },
              encounter2: { id: enc2.id, start: enc2.period.start, end: enc2.period.end },
            });
          }
        }

        // Check for same time
        if (enc1.period?.start === enc2.period?.start) {
          outliers.temporal.sameTime.push({
            patientId,
            time: enc1.period.start,
            encounter1: enc1.id,
            encounter2: enc2.id,
          });
        }
      }
    }
  });

  // Print results
  console.log(`\n📊 Encounter Data Validation Results (${totalEncounters} encounters):\n`);

  console.log('⏱️  Duration Analysis:');
  console.log(`  - Very short encounters (<1 min): ${outliers.durations.veryShort.length}`);
  console.log(`  - Very long encounters (>24 hrs): ${outliers.durations.veryLong.length}`);
  console.log(`  - Negative duration: ${outliers.durations.negative.length}`);
  console.log(`  - No end time: ${outliers.durations.noEndTime.length}`);
  console.log(`  - Average duration: ${(outliers.durations.statistics.average / (60 * 1000)).toFixed(2)} minutes`);
  console.log(`  - Median duration: ${(outliers.durations.statistics.median / (60 * 1000)).toFixed(2)} minutes`);

  console.log('\n📋 Status Distribution:');
  Object.entries(outliers.status.distribution)
    .sort(([,a], [,b]) => b - a)
    .forEach(([status, count]) => {
      console.log(`  - ${status}: ${count}`);
    });

  console.log('\n🏥 Top 10 Encounter Types:');
  Object.entries(outliers.types.distribution)
    .sort(([,a], [,b]) => b - a)
    .slice(0, 10)
    .forEach(([type, count]) => {
      console.log(`  - ${type}: ${count}`);
    });

  console.log('\n👥 Participant Analysis:');
  console.log(`  - No participants: ${outliers.participants.noParticipants.length}`);
  console.log(`  - Many participants (>5): ${outliers.participants.manyParticipants.length}`);
  console.log(`  - Average participants: ${outliers.participants.participantStats.average.toFixed(2)}`);

  console.log('\n🕐 Temporal Patterns:');
  console.log(`  - Same time encounters: ${outliers.temporal.sameTime.length}`);
  console.log(`  - Overlapping encounters: ${outliers.temporal.overlap.length}`);
  console.log(`  - Peak hours:`, Object.entries(outliers.temporal.clustering)
    .sort(([,a], [,b]) => b - a)
    .slice(0, 3)
    .map(([hour, count]) => `${hour}:00 (${count})`).join(', '));

  if (outliers.durations.veryShort.length > 0) {
    console.log('\n⚡ Sample Very Short Encounters:');
    outliers.durations.veryShort.slice(0, 3).forEach(enc => {
      console.log(`  - ${enc.type}: ${enc.duration}s (${enc.start} to ${enc.end})`);
    });
  }

  if (outliers.durations.veryLong.length > 0) {
    console.log('\n🕰️  Sample Very Long Encounters:');
    outliers.durations.veryLong.slice(0, 3).forEach(enc => {
      console.log(`  - ${enc.type}: ${enc.duration.toFixed(2)}hrs (${enc.start} to ${enc.end})`);
    });
  }

  return outliers;
}

if (require.main === module) {
  const sampleSize = process.argv[2] ? parseInt(process.argv[2]) : 50;
  validateEncounterData(sampleSize);
}

