import { readdirSync } from 'fs';
import { join } from 'path';
import { loadFhirBundle } from '../loaders/fhir-loader';
import { getResourcesByType } from '../schema';

/**
 * Cross-Resource Validation - Check for consistency between different resource types
 */

const DATA_PATH = '/Users/hrishioa/Dropbox/Projects/Southbridge/experiments/sealed-agents/tests/healthcare-ehr-langton/data/fhir';

interface CrossResourceOutliers {
  referenceIntegrity: {
    brokenPatientRefs: any[];
    brokenEncounterRefs: any[];
    orphanedResources: any[];
  };
  temporalConsistency: {
    observationsBeforeBirth: any[];
    encountersBeforeBirth: any[];
    conditionsBeforeBirth: any[];
    observationsAfterDeath: any[];
    encountersAfterDeath: any[];
    futureEvents: any[];
  };
  clinicalLogic: {
    unreasonableAges: any[];
    pediatricAdultMismatch: any[];
    chronologicalIssues: any[];
  };
  dataQuality: {
    missingCriticalData: any[];
    duplicateResources: any[];
    inconsistentTimezones: any[];
  };
}

function parseDate(dateString: string): Date {
  return new Date(dateString);
}

function calculateAge(birthDate: string, eventDate: string): number {
  const birth = parseDate(birthDate);
  const event = parseDate(eventDate);
  return (event.getTime() - birth.getTime()) / (1000 * 60 * 60 * 24 * 365.25);
}

function extractTimezone(dateString: string): string {
  const match = dateString.match(/([+-]\d{2}:\d{2})$/);
  return match ? match[1] : 'unknown';
}

export function validateCrossResourceData(sampleSize: number = 50): CrossResourceOutliers {
  const files = readdirSync(DATA_PATH).filter(f => f.endsWith('.json')).slice(0, sampleSize);

  const outliers: CrossResourceOutliers = {
    referenceIntegrity: {
      brokenPatientRefs: [],
      brokenEncounterRefs: [],
      orphanedResources: [],
    },
    temporalConsistency: {
      observationsBeforeBirth: [],
      encountersBeforeBirth: [],
      conditionsBeforeBirth: [],
      observationsAfterDeath: [],
      encountersAfterDeath: [],
      futureEvents: [],
    },
    clinicalLogic: {
      unreasonableAges: [],
      pediatricAdultMismatch: [],
      chronologicalIssues: [],
    },
    dataQuality: {
      missingCriticalData: [],
      duplicateResources: [],
      inconsistentTimezones: [],
    },
  };

  console.log(`🔍 Validating cross-resource consistency in ${files.length} files...\n`);

  const currentDate = new Date();

  for (const [index, fileName] of files.entries()) {
    if (index % 10 === 0) {
      console.log(`Progress: ${index}/${files.length} files`);
    }

    const result = loadFhirBundle(join(DATA_PATH, fileName));
    if (!result.success || !result.bundle) continue;

    const patients = getResourcesByType(result.bundle, 'Patient');
    const encounters = getResourcesByType(result.bundle, 'Encounter');
    const observations = getResourcesByType(result.bundle, 'Observation');
    const conditions = getResourcesByType(result.bundle, 'Condition');

    // Skip if no patient resource
    if (patients.length === 0) {
      outliers.dataQuality.missingCriticalData.push({
        file: fileName,
        issue: 'No patient resource found',
      });
      continue;
    }

    const patient = patients[0];
    const patientId = patient.id;
    const patientBirthDate = patient.birthDate;
    const patientDeathDate = patient.deceasedDateTime;

    // Create lookup maps
    const encounterIds = new Set(encounters.map(e => e.id));
    const allTimezones = new Set<string>();

    // Check reference integrity
    observations.forEach(obs => {
      // Check patient references
      const patientRef = obs.subject?.reference;
      if (patientRef && !patientRef.includes(patientId || '')) {
        outliers.referenceIntegrity.brokenPatientRefs.push({
          file: fileName,
          resourceId: obs.id,
          resourceType: 'Observation',
          expectedPatientId: patientId,
          actualRef: patientRef,
        });
      }

      // Check encounter references
      const encounterRef = obs.encounter?.reference;
      if (encounterRef) {
        const encounterId = encounterRef.split(':').pop();
        if (encounterId && !encounterIds.has(encounterId)) {
          outliers.referenceIntegrity.brokenEncounterRefs.push({
            file: fileName,
            resourceId: obs.id,
            resourceType: 'Observation',
            encounterRef: encounterRef,
          });
        }
      }

      // Check temporal consistency
      if (obs.effectiveDateTime) {
        const obsDate = parseDate(obs.effectiveDateTime);
        const timezone = extractTimezone(obs.effectiveDateTime);
        allTimezones.add(timezone);

        // Check if before birth
        if (patientBirthDate && obsDate < parseDate(patientBirthDate)) {
          outliers.temporalConsistency.observationsBeforeBirth.push({
            file: fileName,
            resourceId: obs.id,
            obsDate: obs.effectiveDateTime,
            birthDate: patientBirthDate,
            obsType: obs.code?.text,
          });
        }

        // Check if after death
        if (patientDeathDate && obsDate > parseDate(patientDeathDate)) {
          outliers.temporalConsistency.observationsAfterDeath.push({
            file: fileName,
            resourceId: obs.id,
            obsDate: obs.effectiveDateTime,
            deathDate: patientDeathDate,
            obsType: obs.code?.text,
          });
        }

        // Check if in future
        if (obsDate > currentDate) {
          outliers.temporalConsistency.futureEvents.push({
            file: fileName,
            resourceId: obs.id,
            resourceType: 'Observation',
            eventDate: obs.effectiveDateTime,
            eventType: obs.code?.text,
          });
        }

        // Check for clinical logic issues
        if (patientBirthDate) {
          const ageAtObservation = calculateAge(patientBirthDate, obs.effectiveDateTime);

          // Check for unreasonable ages
          if (ageAtObservation < 0 || ageAtObservation > 150) {
            outliers.clinicalLogic.unreasonableAges.push({
              file: fileName,
              resourceId: obs.id,
              resourceType: 'Observation',
              age: ageAtObservation.toFixed(2),
              eventDate: obs.effectiveDateTime,
              birthDate: patientBirthDate,
            });
          }

          // Check for pediatric/adult mismatches
          const obsType = obs.code?.text?.toLowerCase() || '';
          if (ageAtObservation < 18 && obsType.includes('prostate')) {
            outliers.clinicalLogic.pediatricAdultMismatch.push({
              file: fileName,
              resourceId: obs.id,
              age: ageAtObservation.toFixed(2),
              obsType: obs.code?.text,
              issue: 'Prostate observation in pediatric patient',
            });
          }

          if (ageAtObservation > 65 && obsType.includes('well child')) {
            outliers.clinicalLogic.pediatricAdultMismatch.push({
              file: fileName,
              resourceId: obs.id,
              age: ageAtObservation.toFixed(2),
              obsType: obs.code?.text,
              issue: 'Well child visit in elderly patient',
            });
          }
        }
      }
    });

    // Check encounters
    encounters.forEach(encounter => {
      if (encounter.period?.start) {
        const encDate = parseDate(encounter.period.start);
        const timezone = extractTimezone(encounter.period.start);
        allTimezones.add(timezone);

        // Check if before birth
        if (patientBirthDate && encDate < parseDate(patientBirthDate)) {
          outliers.temporalConsistency.encountersBeforeBirth.push({
            file: fileName,
            resourceId: encounter.id,
            encDate: encounter.period.start,
            birthDate: patientBirthDate,
            encType: encounter.type?.[0]?.text,
          });
        }

        // Check if in future
        if (encDate > currentDate) {
          outliers.temporalConsistency.futureEvents.push({
            file: fileName,
            resourceId: encounter.id,
            resourceType: 'Encounter',
            eventDate: encounter.period.start,
            eventType: encounter.type?.[0]?.text,
          });
        }
      }
    });

    // Check conditions
    conditions.forEach(condition => {
      if (condition.onsetDateTime) {
        const condDate = parseDate(condition.onsetDateTime);
        const timezone = extractTimezone(condition.onsetDateTime);
        allTimezones.add(timezone);

        // Check if before birth
        if (patientBirthDate && condDate < parseDate(patientBirthDate)) {
          outliers.temporalConsistency.conditionsBeforeBirth.push({
            file: fileName,
            resourceId: condition.id,
            condDate: condition.onsetDateTime,
            birthDate: patientBirthDate,
            condType: condition.code?.text,
          });
        }
      }
    });

    // Check for inconsistent timezones
    if (allTimezones.size > 1) {
      outliers.dataQuality.inconsistentTimezones.push({
        file: fileName,
        timezones: Array.from(allTimezones),
      });
    }

    // Check for duplicate resources (same type, same patient, same time)
    const observationsByType: { [key: string]: any[] } = {};
    observations.forEach(obs => {
      const key = `${obs.code?.text || 'unknown'}_${obs.effectiveDateTime}`;
      if (!observationsByType[key]) {
        observationsByType[key] = [];
      }
      observationsByType[key].push(obs);
    });

    Object.entries(observationsByType).forEach(([key, obs]) => {
      if (obs.length > 1) {
        outliers.dataQuality.duplicateResources.push({
          file: fileName,
          resourceType: 'Observation',
          count: obs.length,
          details: key,
          ids: obs.map(o => o.id),
        });
      }
    });
  }

  // Print results
  console.log(`\n📊 Cross-Resource Validation Results:\n`);

  console.log('🔗 Reference Integrity:');
  console.log(`  - Broken patient references: ${outliers.referenceIntegrity.brokenPatientRefs.length}`);
  console.log(`  - Broken encounter references: ${outliers.referenceIntegrity.brokenEncounterRefs.length}`);
  console.log(`  - Orphaned resources: ${outliers.referenceIntegrity.orphanedResources.length}`);

  console.log('\n⏰ Temporal Consistency:');
  console.log(`  - Observations before birth: ${outliers.temporalConsistency.observationsBeforeBirth.length}`);
  console.log(`  - Encounters before birth: ${outliers.temporalConsistency.encountersBeforeBirth.length}`);
  console.log(`  - Conditions before birth: ${outliers.temporalConsistency.conditionsBeforeBirth.length}`);
  console.log(`  - Observations after death: ${outliers.temporalConsistency.observationsAfterDeath.length}`);
  console.log(`  - Encounters after death: ${outliers.temporalConsistency.encountersAfterDeath.length}`);
  console.log(`  - Future events: ${outliers.temporalConsistency.futureEvents.length}`);

  console.log('\n🏥 Clinical Logic:');
  console.log(`  - Unreasonable ages: ${outliers.clinicalLogic.unreasonableAges.length}`);
  console.log(`  - Pediatric/adult mismatches: ${outliers.clinicalLogic.pediatricAdultMismatch.length}`);
  console.log(`  - Chronological issues: ${outliers.clinicalLogic.chronologicalIssues.length}`);

  console.log('\n📊 Data Quality:');
  console.log(`  - Missing critical data: ${outliers.dataQuality.missingCriticalData.length}`);
  console.log(`  - Duplicate resources: ${outliers.dataQuality.duplicateResources.length}`);
  console.log(`  - Inconsistent timezones: ${outliers.dataQuality.inconsistentTimezones.length}`);

  // Show samples of key issues
  if (outliers.temporalConsistency.observationsBeforeBirth.length > 0) {
    console.log('\n🚨 Sample Observations Before Birth:');
    outliers.temporalConsistency.observationsBeforeBirth.slice(0, 3).forEach(item => {
      console.log(`  - ${item.obsType}: ${item.obsDate} (birth: ${item.birthDate})`);
    });
  }

  if (outliers.temporalConsistency.futureEvents.length > 0) {
    console.log('\n🔮 Sample Future Events:');
    outliers.temporalConsistency.futureEvents.slice(0, 3).forEach(item => {
      console.log(`  - ${item.resourceType}: ${item.eventType} on ${item.eventDate}`);
    });
  }

  if (outliers.dataQuality.duplicateResources.length > 0) {
    console.log('\n👥 Sample Duplicate Resources:');
    outliers.dataQuality.duplicateResources.slice(0, 3).forEach(item => {
      console.log(`  - ${item.resourceType}: ${item.count} duplicates (${item.details})`);
    });
  }

  return outliers;
}

if (require.main === module) {
  const sampleSize = process.argv[2] ? parseInt(process.argv[2]) : 50;
  validateCrossResourceData(sampleSize);
}

import { validatePatientData } from './patient-data-validation';
import { validateObservationData } from './observation-data-validation';
import { validateEncounterData } from './encounter-data-validation';
import { validateCrossResourceData } from './cross-resource-validation';

/**
 * Comprehensive Outlier Analysis
 * 
 * This script runs all validation tests and provides a consolidated report
 * of outliers and data quality issues across the entire dataset.
 */

interface ComprehensiveReport {
  executionTime: string;
  sampleSize: number;
  summary: {
    totalIssues: number;
    criticalIssues: number;
    warningIssues: number;
    infoIssues: number;
  };
  findings: {
    category: string;
    severity: 'critical' | 'warning' | 'info';
    issue: string;
    count: number;
    examples?: any[];
    recommendation?: string;
  }[];
  schemaRecommendations: {
    field: string;
    currentValidation: string;
    recommendedValidation: string;
    reasoning: string;
  }[];
}

export function runComprehensiveAnalysis(sampleSize: number = 100): ComprehensiveReport {
  const startTime = new Date();

  console.log('🔍 Running Comprehensive Outlier Analysis...\n');
  console.log('=' .repeat(60));

  // Run all validation tests
  console.log('\n1. Patient Data Validation');
  console.log('-'.repeat(30));
  const patientOutliers = validatePatientData(sampleSize);

  console.log('\n2. Observation Data Validation');
  console.log('-'.repeat(30));
  const observationOutliers = validateObservationData(sampleSize);

  console.log('\n3. Encounter Data Validation');
  console.log('-'.repeat(30));
  const encounterOutliers = validateEncounterData(sampleSize);

  console.log('\n4. Cross-Resource Validation');
  console.log('-'.repeat(30));
  const crossResourceOutliers = validateCrossResourceData(sampleSize);

  const endTime = new Date();
  const executionTime = `${(endTime.getTime() - startTime.getTime()) / 1000}s`;

  // Consolidate findings
  const findings: ComprehensiveReport['findings'] = [];

  // Patient data findings
  findings.push({
    category: 'Patient Demographics',
    severity: 'info',
    issue: 'Non-standard name patterns',
    count: patientOutliers.names.nonStandardPattern.length,
    examples: patientOutliers.names.nonStandardPattern.slice(0, 2),
    recommendation: 'Update schema to allow for edge cases in synthetic names'
  });

  findings.push({
    category: 'Patient Demographics',
    severity: 'info',
    issue: 'January 1st birth dates',
    count: patientOutliers.birthDates.january1st.length,
    recommendation: 'Note that some birth dates may be defaults/anonymized'
  });

  findings.push({
    category: 'Patient Demographics',
    severity: 'warning',
    issue: 'Missing identifier types',
    count: patientOutliers.identifiers.missingTypes.length,
    recommendation: 'Consider making some identifier types required'
  });

  // Observation data findings
  findings.push({
    category: 'Observation Values',
    severity: 'critical',
    issue: 'Unit format inconsistencies',
    count: observationOutliers.valueOutliers.tooLow.length,
    examples: observationOutliers.valueOutliers.tooLow.slice(0, 2),
    recommendation: 'Handle scientific notation in lab values (e.g., 10*3/uL)'
  });

  findings.push({
    category: 'Observation Values',
    severity: 'warning',
    issue: 'Unit inconsistencies across same observation types',
    count: Object.keys(observationOutliers.unitInconsistency).filter(key => 
      Object.keys(observationOutliers.unitInconsistency[key]).length > 1
    ).length,
    examples: Object.entries(observationOutliers.unitInconsistency)
      .filter(([, units]) => Object.keys(units).length > 1)
      .slice(0, 2),
    recommendation: 'Standardize units or add unit conversion logic'
  });

  // Encounter data findings
  findings.push({
    category: 'Encounter Duration',
    severity: 'info',
    issue: 'Very long encounters (>24 hours)',
    count: encounterOutliers.durations.veryLong.length,
    examples: encounterOutliers.durations.veryLong.slice(0, 2),
    recommendation: 'These are clinically appropriate for hospice, rehab, etc.'
  });

  findings.push({
    category: 'Encounter Timing',
    severity: 'warning',
    issue: 'Overlapping encounters for same patient',
    count: encounterOutliers.temporal.overlap.length,
    examples: encounterOutliers.temporal.overlap.slice(0, 2),
    recommendation: 'Add validation to prevent overlapping encounters'
  });

  findings.push({
    category: 'Encounter Timing',
    severity: 'warning',
    issue: 'Encounters at exact same time',
    count: encounterOutliers.temporal.sameTime.length,
    examples: encounterOutliers.temporal.sameTime.slice(0, 2),
    recommendation: 'Consider adding millisecond precision to prevent duplicates'
  });

  // Cross-resource findings
  findings.push({
