import { readdirSync } from 'fs';
import { join } from 'path';
import { loadFhirBundle } from '../loaders/fhir-loader';
import { 
  BundleSchema, 
  getResourcesByType, 
  extractPatientSummary,
  extractObservationSummary,
  extractEncounterSummary
} from '../schema';

/**
 * Enhanced Validation Example
 * 
 * This script demonstrates how to use the updated schemas with knowledge
 * of outliers and edge cases discovered during comprehensive validation.
 */

const DATA_PATH = '/Users/hrishioa/Dropbox/Projects/Southbridge/experiments/sealed-agents/tests/healthcare-ehr-langton/data/fhir';

// Enhanced validation functions that handle known outliers
function validateLabValue(obs: any): { isValid: boolean; normalizedValue?: number; issues: string[] } {
  const issues: string[] = [];
  let isValid = true;
  let normalizedValue: number | undefined;

  if (obs.valueQuantity?.value && obs.valueQuantity?.unit) {
    let value = obs.valueQuantity.value;
    const unit = obs.valueQuantity.unit;

    // Handle scientific notation in units (e.g., "10*3/uL")
    if (unit.includes('10*')) {
      const multiplierMatch = unit.match(/10\*(\d+)/);
      if (multiplierMatch) {
        const exponent = parseInt(multiplierMatch[1]);
        normalizedValue = value * Math.pow(10, exponent);
        issues.push(`Applied scientific notation: ${value} × 10^${exponent} = ${normalizedValue}`);
      }
    } else {
      normalizedValue = value;
    }

    // Check for clinically appropriate negative values
    const obsType = obs.code?.text?.toLowerCase() || '';
    if (value < 0 && !obsType.includes('t-score') && !obsType.includes('change') && !obsType.includes('delta')) {
      issues.push('Negative value may be inappropriate for this observation type');
      isValid = false;
    }
  }

  return { isValid, normalizedValue, issues };
}

function validatePatientName(name: any): { isValid: boolean; issues: string[] } {
  const issues: string[] = [];
  let isValid = true;

  if (name.given) {
    name.given.forEach((givenName: string) => {
      // Allow for non-standard Synthea patterns (discovered outliers)
      if (!/^[A-Za-z\s\u00C0-\u017F]+\d*$/.test(givenName)) {
        issues.push(`Non-standard name pattern: ${givenName}`);
        // Note: This is acceptable for synthetic data with international characters
      }
    });
  }

  if (name.family) {
    if (!/^[A-Za-z\s\u00C0-\u017F]+\d*$/.test(name.family)) {
      issues.push(`Non-standard family name pattern: ${name.family}`);
      // Note: This is acceptable for synthetic data with international characters
    }
  }

  return { isValid, issues };
}

function validateEncounterTiming(encounters: any[]): { isValid: boolean; issues: string[] } {
  const issues: string[] = [];
  let isValid = true;

  // Check for overlapping encounters
  for (let i = 0; i < encounters.length; i++) {
    for (let j = i + 1; j < encounters.length; j++) {
      const enc1 = encounters[i];
      const enc2 = encounters[j];

      if (enc1.period?.start && enc1.period?.end && enc2.period?.start && enc2.period?.end) {
        const start1 = new Date(enc1.period.start);
        const end1 = new Date(enc1.period.end);
        const start2 = new Date(enc2.period.start);
        const end2 = new Date(enc2.period.end);

        if (start1 < end2 && start2 < end1) {
          issues.push(`Overlapping encounters: ${enc1.id} and ${enc2.id}`);
          isValid = false;
        }
      }

      // Check for exact same time (millisecond precision issue)
      if (enc1.period?.start === enc2.period?.start) {
        issues.push(`Encounters at exact same time: ${enc1.id} and ${enc2.id}`);
        // Note: This is a known issue in synthetic data generation
      }
    }
  }

  return { isValid, issues };
}

function validateTemporalConsistency(patient: any, observations: any[], encounters: any[]): { isValid: boolean; issues: string[] } {
  const issues: string[] = [];
  let isValid = true;

  if (!patient.birthDate) {
    issues.push('No birth date for temporal validation');
    return { isValid: false, issues };
  }

  const birthDate = new Date(patient.birthDate);

  // Check observations against birth date (handle same-day timing issue)
  observations.forEach(obs => {
    if (obs.effectiveDateTime) {
      const obsDate = new Date(obs.effectiveDateTime);
      const birthDateOnly = new Date(patient.birthDate + 'T00:00:00');

      if (obsDate < birthDateOnly) {
        issues.push(`Observation before birth: ${obs.code?.text} at ${obs.effectiveDateTime}`);
        // Note: This is often a same-day timing issue, not a real problem
      }
    }
  });

  // Check encounters against birth date
  encounters.forEach(enc => {
    if (enc.period?.start) {
      const encDate = new Date(enc.period.start);
      if (encDate < birthDate) {
        issues.push(`Encounter before birth: ${enc.type?.[0]?.text} at ${enc.period.start}`);
        isValid = false;
      }
    }
  });

  return { isValid, issues };
}

export function demonstrateEnhancedValidation(sampleSize: number = 10) {
  const files = readdirSync(DATA_PATH).filter(f => f.endsWith('.json')).slice(0, sampleSize);

  console.log(`🔍 Enhanced Validation Demonstration (${files.length} files)\n`);

  let totalIssues = 0;
  let handledOutliers = 0;

  for (const [index, fileName] of files.entries()) {
    console.log(`\n--- File ${index + 1}: ${fileName} ---`);

    const result = loadFhirBundle(join(DATA_PATH, fileName));
    if (!result.success || !result.bundle) {
      console.log('❌ Failed to load bundle');
      continue;
    }

    const bundle = result.bundle;
    const patients = getResourcesByType(bundle, 'Patient');
    const observations = getResourcesByType(bundle, 'Observation');
    const encounters = getResourcesByType(bundle, 'Encounter');

    if (patients.length === 0) {
      console.log('❌ No patient found');
      continue;
    }

    const patient = patients[0];
    const patientSummary = extractPatientSummary(patient);
    console.log(`👤 Patient: ${patientSummary.fullName} (${patientSummary.gender}, born ${patientSummary.birthDate})`);

    // Validate patient name (handle outliers)
    const nameValidation = validatePatientName(patient.name?.[0]);
    if (nameValidation.issues.length > 0) {
      console.log(`   💡 Name issues: ${nameValidation.issues.join(', ')}`);
      handledOutliers++;
    }

    // Validate lab values (handle scientific notation)
    const labObs = observations.filter(obs => 
      obs.code?.text?.includes('volume') || 
      obs.code?.text?.includes('count') ||
      obs.code?.text?.includes('Mass')
    );

    labObs.slice(0, 3).forEach(obs => {
      const labValidation = validateLabValue(obs);
      if (labValidation.issues.length > 0) {
        console.log(`   🔬 Lab value: ${obs.code?.text}`);
        console.log(`      ${labValidation.issues.join(', ')}`);
        handledOutliers++;
      }
    });

    // Validate encounter timing
    const timingValidation = validateEncounterTiming(encounters);
    if (timingValidation.issues.length > 0) {
      console.log(`   ⏰ Timing issues: ${timingValidation.issues.join(', ')}`);
      totalIssues += timingValidation.issues.length;
    }

    // Validate temporal consistency
    const temporalValidation = validateTemporalConsistency(patient, observations, encounters);
    if (temporalValidation.issues.length > 0) {
      console.log(`   📅 Temporal issues: ${temporalValidation.issues.slice(0, 2).join(', ')}`);
      if (temporalValidation.issues.length > 2) {
        console.log(`      ... and ${temporalValidation.issues.length - 2} more`);
      }
      totalIssues += temporalValidation.issues.length;
    }

    console.log(`   📊 Resources: ${patients.length} patients, ${observations.length} observations, ${encounters.length} encounters`);
  }

  console.log(`\n📊 Enhanced Validation Summary:`);
  console.log(`  - Total issues detected: ${totalIssues}`);
  console.log(`  - Handled outliers: ${handledOutliers}`);
  console.log(`  - Files processed: ${files.length}`);

  console.log(`\n💡 Key Insights:`);
  console.log(`  - Scientific notation in lab units is common and expected`);
  console.log(`  - Name patterns vary due to international characters`);
  console.log(`  - Same-day birth/observation timing is a known edge case`);
  console.log(`  - Encounter overlaps are rare but should be monitored`);
  console.log(`  - Temporal validation needs birth date/time precision handling`);

  return { totalIssues, handledOutliers };
}

if (require.main === module) {
  const sampleSize = process.argv[2] ? parseInt(process.argv[2]) : 10;
  demonstrateEnhancedValidation(sampleSize);
}
